func TestWaitForDownloadExitsOnTerminalStatusWithoutURL(t *testing.T) {
	var calls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		if r.URL.Path != "/order_products/42/prepare" {
			t.Fatalf("unexpected path %s", r.URL.Path)
		}
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, `{"status":"error"}`)
	}))
	defer server.Close()

	c := client.New(&config.Config{BaseURL: server.URL}, time.Second, 0)
	c.NoCache = true
	_, err := waitForDownload(context.Background(), c, "42", nil, time.Millisecond, time.Second)
	if err == nil {
		t.Fatal("waitForDownload returned nil error for terminal status without URL")
	}
	if !strings.Contains(err.Error(), `download failed with status "error"`) {
		t.Fatalf("waitForDownload error = %v, want terminal status", err)
	}
	if got := calls.Load(); got != 1 {
		t.Fatalf("server calls = %d, want 1", got)
	}
}

func TestLibraryDownloadSubcommandsSendExplicitZeroIndex(t *testing.T) {
	for _, tc := range []struct {
		name string
		args []string
		path string
	}{
		{
			name: "prepare",
			args: []string{"library", "prepare-download", "42", "--index", "0", "--data-source", "live", "--no-cache"},
			path: "/order_products/42/prepare",
		},
		{
			name: "check",
			args: []string{"library", "check-download", "42", "--index", "0", "--data-source", "live", "--no-cache"},
			path: "/order_products/42/check",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			var seen atomic.Bool
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				seen.Store(true)
				if r.URL.Path != tc.path {
					t.Fatalf("path = %s, want %s", r.URL.Path, tc.path)
				}
				if got := r.URL.Query().Get("index"); got != "0" {
					t.Fatalf("index query = %q, want 0; raw query %q", got, r.URL.RawQuery)
				}
				w.Header().Set("Content-Type", "application/json")
				fmt.Fprint(w, `{"status":"ready","url":"https://example.invalid/file.pdf"}`)
			}))
			defer server.Close()

			t.Setenv("DRIVETHRURPG_BASE_URL", server.URL)
			t.Setenv("DRIVETHRURPG_APPLICATION_KEY", "")
			t.Setenv("DRIVETHRURPG_DTRPG_TOKEN", "")
			t.Setenv("DRIVETHRURPG_CONFIG", t.TempDir()+"/config.toml")

			cmd := RootCmd()
			var out bytes.Buffer
			cmd.SetOut(&out)
			cmd.SetErr(&out)
			cmd.SetArgs(tc.args)
			cmd.SilenceErrors = true
			cmd.SilenceUsage = true
			if err := cmd.Execute(); err != nil {
				t.Fatalf("command failed: %v\n%s", err, out.String())
			}
			if !seen.Load() {
				t.Fatal("test server was not called")
			}
		})
	}
}

func TestFilenameFromResponseDecodesRFC5987Filename(t *testing.T) {
	if got := filenameFromResponse(`attachment; filename*=UTF-8''my%20file.pdf`, "https://example.invalid/fallback.pdf"); got != "my file.pdf" {
		t.Fatalf("UTF-8 filename* = %q, want my file.pdf", got)
	}
	if got := filenameFromResponse(`attachment; filename*=ISO-8859-1''caf%E9.pdf`, "https://example.invalid/fallback.pdf"); got != "café.pdf" {
		t.Fatalf("ISO-8859-1 filename* = %q, want café.pdf", got)
	}
	if got := filenameFromResponse(`attachment; filename="plain.pdf"; filename*=UTF-8''encoded.pdf`, "https://example.invalid/fallback.pdf"); got != "plain.pdf" {
		t.Fatalf("plain filename precedence = %q, want plain.pdf", got)
	}
}
